import os
import hashlib
import hmac
import unicodedata
import re
from pathlib import PurePosixPath
from urllib.parse import unquote

# Secure file serving module with multi-layer path validation
# Supports internationalized filenames via Unicode normalization

BASE_DIR = '/var/www/static/uploads'
ALLOWED_EXTENSIONS = {'.png', '.jpg', '.jpeg', '.gif', '.pdf', '.txt', '.doc'}
MAX_PATH_LENGTH = 255
SERVER_SECRET = os.urandom(32)


def _generate_access_token(username, filepath):
    """Generate HMAC token for authorized file access."""
    msg = f"{username}:{filepath}".encode('utf-8')
    return hmac.new(SERVER_SECRET, msg, hashlib.sha256).hexdigest()


def _validate_access_token(username, filepath, token):
    """Constant-time token validation."""
    expected = _generate_access_token(username, filepath)
    return hmac.compare_digest(expected, token)


def _check_path_traversal(user_path):
    """Multi-layer path traversal prevention.

    Checks for:
    - Direct '..' components
    - URL-encoded traversal sequences
    - Null bytes
    - Backslash variants
    - Absolute paths
    """
    # Check for null bytes
    if '\x00' in user_path:
        return False

    # Check for absolute paths
    if user_path.startswith('/'):
        return False

    # Check for backslash (Windows-style traversal)
    if '\\' in user_path:
        return False

    # URL decode and check again
    decoded = unquote(user_path)
    if '..' in decoded:
        return False

    # Use PurePosixPath to resolve and check components
    path = PurePosixPath(decoded)
    for part in path.parts:
        if part in ('..', '.') or part.startswith('~'):
            return False

    # Verify no path component is empty (double slashes)
    if '//' in decoded:
        return False

    return True


def _check_extension(filename):
    """Validate file extension against allowlist."""
    _, ext = os.path.splitext(filename)
    return ext.lower() in ALLOWED_EXTENSIONS


def _sanitize_filename(filename):
    """Remove potentially dangerous characters from filename."""
    # Strip leading/trailing whitespace and dots
    sanitized = filename.strip('. \t\n\r')
    # Remove control characters
    sanitized = re.sub(r'[\x00-\x1f\x7f]', '', sanitized)
    return sanitized


def _normalize_for_filesystem(filepath):
    """Normalize Unicode for consistent filesystem access.

    Different Unicode representations of the same character
    (e.g., e\u0301 vs \xe9) should map to the same file.
    Uses NFC normalization as recommended by Unicode consortium.
    """
    return unicodedata.normalize('NFC', filepath)


def serve_file(username, requested_path, access_token):
    """Serve a file with full security validation.

    Security layers:
    1. Access token verification
    2. Path length check
    3. Path traversal detection
    4. Extension allowlist
    5. Filename sanitization
    6. Final resolved path containment check
    """
    if not username or not requested_path:
        return {'error': 'Missing required parameters', 'status': 400}

    # Layer 1: Verify access token
    if not _validate_access_token(username, requested_path, access_token):
        return {'error': 'Invalid access token', 'status': 403}

    # Layer 2: Path length
    if len(requested_path) > MAX_PATH_LENGTH:
        return {'error': 'Path too long', 'status': 400}

    # Layer 3: Path traversal check on the raw input
    if not _check_path_traversal(requested_path):
        return {'error': 'Invalid path', 'status': 400}

    # Layer 4: Extension check
    if not _check_extension(requested_path):
        return {'error': 'File type not allowed', 'status': 403}

    # Layer 5: Sanitize the filename component
    parts = requested_path.rsplit('/', 1)
    if len(parts) == 2:
        directory, filename = parts
        filename = _sanitize_filename(filename)
        sanitized_path = f"{directory}/{filename}"
    else:
        sanitized_path = _sanitize_filename(requested_path)

    # Layer 6: Unicode normalization for filesystem consistency
    normalized_path = _normalize_for_filesystem(sanitized_path)

    # Construct full path and verify containment
    full_path = os.path.join(BASE_DIR, normalized_path)
    real_path = os.path.realpath(full_path)

    # Final containment check
    if not real_path.startswith(os.path.realpath(BASE_DIR)):
        return {'error': 'Access denied', 'status': 403}

    if not os.path.isfile(real_path):
        return {'error': 'File not found', 'status': 404}

    # Read and return file
    with open(real_path, 'rb') as f:
        content = f.read()

    return {
        'content': content,
        'filename': os.path.basename(real_path),
        'status': 200
    }


def grant_access(username, filepath):
    """Grant a user access to a specific file path."""
    if not _check_path_traversal(filepath):
        return None
    if not _check_extension(filepath):
        return None
    return _generate_access_token(username, filepath)
